"""Exhaustive Extremal Search over unital multiplication tables.

Enumerates every unital table of order n (the unit row and column are fixed, the
remaining (n-1)^2 entries range over all n values), computes the associativity
defect of each, and reports the defect distribution, the maximisers, and the
tables realising any prescribed target value.

An early-abort variant stops scoring a table as soon as its running defect
exceeds the target, which is a large practical saving when hunting maximisers.
Canonical-form reduction under the (n-1)! relabellings of the non-units removes
the labelling redundancy.
"""

from __future__ import annotations

from itertools import permutations, product
from typing import Dict, Iterator, List, Optional, Tuple

Table = List[List[int]]


def unital_tables(n: int) -> Iterator[Table]:
    """All n^{(n-1)^2} unital tables on {0,...,n-1} with 0 the unit."""
    m = n - 1
    for vals in product(range(n), repeat=m * m):
        t = [[0] * n for _ in range(n)]
        for i in range(n):
            t[0][i] = i
            t[i][0] = i
        k = 0
        for a in range(1, n):
            for b in range(1, n):
                t[a][b] = vals[k]
                k += 1
        yield t


def defect_at_least(table: Table, target: int) -> bool:
    """Early-abort test: does the defect reach `target`?  Stops as soon as it does."""
    n = len(table)
    count = 0
    for a in range(n):
        row = table[a]
        for b in range(n):
            ab = row[b]
            for c in range(n):
                if table[ab][c] != row[table[b][c]]:
                    count += 1
                    if count >= target:
                        return True
    return False


def defect(table: Table) -> int:
    n = len(table)
    return sum(
        1
        for a in range(n)
        for b in range(n)
        for c in range(n)
        if table[table[a][b]][c] != table[a][table[b][c]]
    )


def canonical_form(table: Table) -> Tuple[int, ...]:
    """Lexicographically least table under relabellings fixing the unit."""
    n = len(table)
    best: Optional[Tuple[int, ...]] = None
    for perm in permutations(range(1, n)):
        sigma = [0] + list(perm)
        rel = [[0] * n for _ in range(n)]
        for a in range(n):
            for b in range(n):
                rel[sigma[a]][sigma[b]] = sigma[table[a][b]]
        flat = tuple(rel[a][b] for a in range(n) for b in range(n))
        if best is None or flat < best:
            best = flat
    assert best is not None
    return best


def search(n: int, target: Optional[int] = None) -> Dict[str, object]:
    """Full sweep: distribution, maximisers, and tables hitting `target`."""
    dist: Dict[int, int] = {}
    maximisers: List[Table] = []
    hits: List[Table] = []
    bound = (n - 1) ** 3
    for t in unital_tables(n):
        d = defect(t)
        dist[d] = dist.get(d, 0) + 1
        if d == bound:
            maximisers.append([row[:] for row in t])
        if target is not None and d == target:
            hits.append([row[:] for row in t])
    return {
        "order": n,
        "tables_examined": sum(dist.values()),
        "distribution": dict(sorted(dist.items())),
        "bound": bound,
        "num_maximisers": len(maximisers),
        "num_maximisers_up_to_relabelling": len({canonical_form(t) for t in maximisers}),
        "num_target_hits": len(hits) if target is not None else None,
        "commutative_target_hits": (
            sum(
                1
                for t in hits
                if all(t[a][b] == t[b][a] for a in range(n) for b in range(n))
            )
            if target is not None
            else None
        ),
    }


if __name__ == "__main__":
    for order in (3, 4):
        report = search(order, target=1)
        print(f"\n=== order {order} ===")
        for key, value in report.items():
            print(f"  {key:36s} {value}")

"""Codiscrete Bicategory Audit.

Given a pointed magma as a table, this reports the structure of the associated
one-object bicategory whose hom-category is codiscrete: exactly one 2-cell
between any two 1-cells, horizontal composition the magma product, identity
1-cell the distinguished element.

The audit reports:
  * the number of 1-cells and 2-cells;
  * the associator instances that link DISTINCT 1-cells (there are exactly D of
    them) and the unitor instances that do;
  * strictness, which holds iff the magma is a monoid;
  * the strictly invertible 1-cells, i.e. the elements with a two-sided inverse
    (equivalence of 1-cells, by contrast, is free: every ordered pair of 1-cells
    forms an adjoint equivalence);
  * a check of the pentagon on all quadruples, which passes automatically since
    both routes are parallel 2-cells in a thin hom-category;
  * for a supplied map of magmas, whether the induced pseudofunctor -- which
    exists for ANY map -- is strictly multiplicative, i.e. whether the map is a
    homomorphism.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

Table = List[List[int]]
Triple = Tuple[int, int, int]


def weak_associators(table: Table) -> List[Triple]:
    n = len(table)
    return [
        (a, b, c)
        for a in range(n)
        for b in range(n)
        for c in range(n)
        if table[table[a][b]][c] != table[a][table[b][c]]
    ]


def weak_unitors(table: Table, unit: int = 0) -> Tuple[List[int], List[int]]:
    n = len(table)
    return (
        [a for a in range(n) if table[unit][a] != a],
        [a for a in range(n) if table[a][unit] != a],
    )


def strictly_invertible(table: Table, unit: int = 0) -> List[int]:
    n = len(table)
    return [
        a
        for a in range(n)
        if any(table[a][b] == unit and table[b][a] == unit for b in range(n))
    ]


def bracketings(table: Table, a: int, b: int, c: int, d: int) -> Tuple[int, int, int, int, int]:
    """The five bracketings of a*b*c*d, as elements (i.e. as 1-cells)."""
    m = lambda x, y: table[x][y]
    return (
        m(m(m(a, b), c), d),   # ((ab)c)d   -- the pentagon's source
        m(m(a, m(b, c)), d),   # (a(bc))d
        m(a, m(m(b, c), d)),   # a((bc)d)
        m(a, m(b, m(c, d))),   # a(b(cd))   -- the pentagon's target
        m(m(a, b), m(c, d)),   # (ab)(cd)
    )


def pentagon_audit(table: Table) -> Dict[str, int]:
    """Check the pentagon on every quadruple and measure how weak it really is.

    Route 1 composes three associators through (a(bc))d and a((bc)d); route 2
    composes two through (ab)(cd).  Both are 2-cells from the 1-cell ((ab)c)d to
    the 1-cell a(b(cd)); since the hom-category is thin they are equal, so the
    pentagon commutes on every quadruple.  The audit also counts the quadruples
    on which the five bracketings are not all equal -- those are the quadruples
    where the pentagon is a genuinely weak diagram rather than a trivial one.
    """
    n = len(table)
    failures = 0
    genuinely_weak = 0
    for a in range(n):
        for b in range(n):
            for c in range(n):
                for d in range(n):
                    v = bracketings(table, a, b, c, d)
                    route1 = (v[0], v[1], v[2], v[3])   # three associators
                    route2 = (v[0], v[4], v[3])         # two associators
                    if (route1[0], route1[-1]) != (route2[0], route2[-1]):
                        failures += 1
                    if len(set(v)) > 1:
                        genuinely_weak += 1
    return {"quadruples": n ** 4,
            "pentagon_failures": failures,
            "genuinely_weak_pentagons": genuinely_weak}


def induced_pseudofunctor_strict(src: Table, tgt: Table, f: Sequence[int]) -> bool:
    n = len(src)
    return all(f[src[a][b]] == tgt[f[a]][f[b]] for a in range(n) for b in range(n))


def audit(table: Table, unit: int = 0,
          f: Optional[Sequence[int]] = None,
          target: Optional[Table] = None) -> Dict[str, object]:
    n = len(table)
    wa = weak_associators(table)
    wl, wr = weak_unitors(table, unit)
    unital = not wl and not wr
    report: Dict[str, object] = {
        "one_cells": n,
        "two_cells": n * n,
        "every_two_cell_invertible": True,
        "parallel_two_cells_equal": True,
        "pentagon_audit": pentagon_audit(table),
        "weak_associator_instances": len(wa),
        "left_unitor_defects": wl,
        "right_unitor_defects": wr,
        "strict": unital and not wa,
        "strictly_invertible_one_cells": strictly_invertible(table, unit),
        "every_pair_is_an_adjoint_equivalence": True,
    }
    if f is not None and target is not None:
        report["induced_pseudofunctor_exists"] = True
        report["induced_pseudofunctor_strictly_multiplicative"] = \
            induced_pseudofunctor_strict(table, target, f)
    return report


if __name__ == "__main__":
    n = 4
    shift: Table = [[0] * n for _ in range(n)]
    for i in range(n):
        shift[0][i] = i
        shift[i][0] = i
    for a in range(1, n):
        for b in range(1, n):
            shift[a][b] = (b % (n - 1)) + 1
    group: Table = [[(a + b) % n for b in range(n)] for a in range(n)]

    print("shift magma of order 4")
    for k, v in audit(shift, f=[0, 1, 2, 3], target=group).items():
        print(f"  {k:44s} {v}")
    print("\ncyclic group Z/4")
    for k, v in audit(group).items():
        print(f"  {k:44s} {v}")
